export interface DemoRequest {
  stepId: string;
  phase: DemoPhase;
}

/**
 * DemoResult reports whether demo start restored the step's checkpoint
 * first (a command ran since the step started or was last reset).
 */
export interface DemoResult {
  restored: boolean;
}

/** DemoToken is one element of a step's demo string. */
export interface DemoToken {
  kind: DemoTokenKind;
  /** Key is the canonical key for DemoKey tokens. */
  key?: string;
  /** Text is typed literally for DemoText tokens. */
  text?: string;
  /** PauseMs is the pause for DemoPause tokens. */
  pauseMs?: number;
}

/**
 * DescribeRequest asks what a key sequence runs (ticker glosses for commands
 * missing from tables.gloss).
 */
export interface DescribeRequest {
  keys: string;
}

/** DescribeResult is the agent's playground-describe answer. */
export interface DescribeResult {
  /** Cmd is the command name, or "" when the key is unbound. */
  cmd: string;
  /** Doc is the first line of the docstring. */
  doc: string;
}

/** Diagnostic is the Flymake diagnostic at point (playground--diag-at-point). */
export interface Diagnostic {
  severity: DiagnosticSeverity;
  /** Message is the diagnostic text, first line only. */
  message: string;
  /** Source is the Flymake backend or LSP server, e.g. "eglot", "rustc". */
  source?: string;
  /**
   * Line and Col locate the start of the diagnostic (1-based line,
   * 0-based column).
   */
  line: number;
  col: number;
}

/**
 * DropStepRequest tells sessiond to forget saved progress after
 * POST /progress/reset (sent by the gateway). With LessonID it forgets that
 * lesson's progress and the active step if it belongs to the lesson; with an
 * empty LessonID it forgets all progress and the active step. A forgotten
 * active step emits a StepEvent with status StepDropped.
 */
export interface DropStepRequest {
  lessonId?: string;
}

/** EchoEvent is an echo-area message the agent did not filter as noise. */
export interface EchoEvent {
  t: "echo";
  seq?: number;
  ts?: number;
  text: string;
}

/** EmacsEvent reports supervisor events (architecture.md §5.2, §6). */
export interface EmacsEvent {
  t: "emacs";
  seq?: number;
  ts?: number;
  event: EmacsEventKind;
  /** Frame is set for frame-closed and frame-opened. */
  frame?: FrameKind;
  /**
   * Reason is a short human-readable cause ("C-x C-c", "exit status 1",
   * "module set changed").
   */
  reason?: string;
}

/** EmacsInfo is the short Emacs description in hello and session info. */
export interface EmacsInfo {
  /** Version is emacs-version, e.g. "31.1". */
  version: string;
  /** UptimeMs is the daemon's uptime in milliseconds. */
  uptimeMs: number;
}

/** EmacsStatus is the detailed Emacs description in StatusResult. */
export interface EmacsStatus {
  version: string;
  pid: number;
  uptimeMs: number;
  /** Agent is true while the agent socket is connected. */
  agent: boolean;
  /** Responsive is false after missed heartbeats. */
  responsive: boolean;
}

/** Empty is the request or result of operations that carry nothing ({}). */
export type Empty = Record<string, never>;

/**
 * Envelope is the common part of every event: {"t", "seq", "ts"}. It is
 * embedded in each event struct so that the fields appear flat on the wire.
 *
 * Seq is assigned by sessiond's event bus: monotonic per sessiond process,
 * starting at 1. Ts is milliseconds since the Unix epoch, assigned by
 * sessiond when the event enters the bus. Messages from the agent carry
 * neither (they are omitted when zero).
 */
export interface Envelope {
  t: EventType;
  seq?: number;
  ts?: number;
}

/**
 * ErrorEvent is an error the learner should see (fixture fetch failed,
 * module load error).
 */
export interface ErrorEvent {
  t: "error";
  seq?: number;
  ts?: number;
  code: ErrorCode;
  message: string;
}

/**
 * EvalRequest evaluates an Emacs Lisp form in the daemon (author mode,
 * tests). The gateway only proxies it when features.authorMode is on.
 */
export interface EvalRequest {
  form: string;
  /** TimeoutMs defaults to 2000, maximum 10000. */
  timeoutMs?: number;
}

/**
 * EvalResult is the value as produced by json-serialize; values that cannot
 * be serialised become their printed representation (a string).
 */
export interface EvalResult {
  value: unknown;
}

/**
 * EventCond is true when Command ran at least Min times (default 1) since
 * the step (default) or the lesson started.
 */
export interface EventCond {
  command: string;
  min?: number;
  since?: EventSince;
}

/**
 * EventsClientMessage is a text frame a client may send on /events
 * ({"t":"ping"}). Anything else is ignored.
 */
export interface EventsClientMessage {
  t: string;
}

/** ExitRow is one row of tables/exits.yaml. */
export interface ExitRow {
  id: string;
  /** When must hold against the State document (Predicate semantics). */
  when: Predicate;
  /**
   * Why is a template ("A prompt is open: {minibuffer.prompt}"); {path}
   * placeholders resolve against the State document (see Predicate and
   * ExpandTemplate).
   */
  why: string;
  /** How is the one exit, a template with keys keyified by the browser. */
  how: string;
  /** Flag is an optional short chip ("Narrow", "Def", "Ovwrt"). */
  flag?: string;
}

/**
 * ExitSession is the virtual root "session" that exit-table rows (and only
 * they) may use (frontend.md §6, the header of curriculum/tables/exits.yaml).
 * These facts live in the event stream rather than in the agent's State, so
 * the browser adds them to the document before evaluating the rows:
 * "session.prefix", "session.emacs", "session.mode", "session.echo".
 * Step conditions are evaluated by sessiond and cannot use it.
 */
export interface ExitSession {
  /** Pending prefix from the input tap ("C-x", "C-x r"), null when none. */
  prefix: string | null;
  /**
   * Supervisor condition still current: "frame-closed", "suspended",
   * "restarting", "unresponsive", or null.
   */
  emacs: string | null;
  /** Frame the browser shows: "terminal" or "gui". */
  mode: FrameKind;
  /** Latest echo text until the next key event, or null. */
  echo: string | null;
}

/** FeaturesConfig toggles optional features. */
export interface FeaturesConfig {
  /** StuckReports allows "I'm stuck" reports, default true. */
  stuckReports: boolean;
  /** TelemetryUpload is never on by default. */
  telemetryUpload: boolean;
  /**
   * AuthorMode shows condition results and raw state in lessons and
   * enables rpc eval through the gateway, default false.
   */
  authorMode: boolean;
}

/**
 * FileCond is a predicate on a workspace file. Path is workspace-relative.
 * Exactly one predicate is set: Exists, Contains, NotContains, Regex, or
 * JSONPath with Equals. Files are read through os.Root, capped at 1 MB.
 * With Host "box" the file is on the remote box instead (Path absolute or
 * relative to the box user's home), read over ssh.
 */
export interface FileCond {
  path: string;
  /** Host is "" (the workspace) or BoxHost. */
  host?: string;
  /** Exists: true requires the file to exist, false requires it not to. */
  exists?: boolean;
  /** Contains requires the substring. */
  contains?: string;
  /** NotContains requires the file to exist and not contain the substring. */
  not_contains?: string;
  /** Regex is an RE2 regular expression that must match somewhere. */
  regex?: string;
  /**
   * JSONPath is a dotted path into a JSON file ("package.version",
   * "items.0.name"); Equals is compared with JSON equality.
   */
  json_path?: string;
  equals?: unknown;
}

/** FileEvent reports a workspace change, debounced per path at 200 ms. */
export interface FileEvent {
  t: "file";
  seq?: number;
  ts?: number;
  /** Path is relative to the workspace root (/work), slash-separated. */
  path: string;
  event: FileEventKind;
}

/** FileSpec is one file-visiting buffer in a WindowSpec. */
export interface FileSpec {
  /** Path is relative to the workspace when inside it, else absolute. */
  path: string;
  /** Point is the 1-based buffer position. */
  point: number;
  /** Visible is true when the buffer is shown in a window. */
  visible?: boolean;
}

/** Frames reports which frames currently exist. */
export interface Frames {
  terminal: boolean;
  gui: boolean;
}

/** GUIConfig configures the GUI frame. */
export interface GUIConfig {
  /** Enabled makes the GUI frame available, default true. */
  enabled: boolean;
  /** Geometry is the Xvnc screen size, default "1600x900". */
  geometry: string;
}

/**
 * GapEvent tells a slow subscriber that events from From to To (inclusive)
 * were dropped. The browser should call rpc check or reconnect.
 */
export interface GapEvent {
  t: "gap";
  seq?: number;
  ts?: number;
  from: number;
  to: number;
}

/** HabitRow is one row of tables/habits.yaml. */
export interface HabitRow {
  /** Key is the single key that VS Code users press by habit, e.g. "C-z". */
  key: string;
  /** VSCode is what they meant ("undo"). */
  vscode: string;
  /** Say is the card body. */
  say: string;
}

/** HealthStatus is the body of GET /healthz on sessiond and the gateway. */
export interface HealthStatus {
  ok: boolean;
  /** Reason explains a 503 ("agent not connected", "starting"). */
  reason?: string;
}

/** Heartbeat is POST /internal/sessions/{id}/heartbeat, every 30 s. */
export interface Heartbeat {
  activeWebSockets: number;
}

/** HelloEvent is always the first frame on /events (api.md §3.2). */
export interface HelloEvent {
  t: "hello";
  seq?: number;
  ts?: number;
  /** Protocol is Version. */
  protocol: number;
  /** SessionID is PG_SESSION_ID. */
  sessionId: string;
  /** Mode is the frame kind the browser should show. */
  mode: FrameKind;
  /** Emacs describes the daemon. */
  emacs: EmacsInfo;
  /** Frames reports which frames exist. */
  frames: Frames;
  /** Step is the active step, or null when no scenario is loaded. */
  step: StepRef | null;
  /** Modules is the enabled configuration module set, in load order. */
  modules: string[];
  /**
   * Replayed is true when the hello precedes replayed events (the client
   * connected with ?after= and the gap was still in the ring buffer).
   */
  replayed: boolean;
  /** Lap is the running lap, if any (ScenarioRequest.Lap). */
  lap?: LapInfo;
}

/** HintRequest records that the learner revealed a hint (progress counts it). */
export interface HintRequest {
  stepId: string;
  /** Level is the hint level now shown (1 for the first hint). */
  level: number;
}

/** InternalStuckReport is POST /internal/sessions/{id}/stuck from sessiond. */
export interface InternalStuckReport {
  lessonId?: string;
  stepId?: string;
  note: string;
  events: unknown[];
}

/** InviteLoginRequest is POST /api/v1/auth/invite. */
export interface InviteLoginRequest {
  code: string;
}

/** InvitesConfig configures invite codes. */
export interface InvitesConfig {
  /**
   * File has one code per line with optional label, uses=N and
   * until=YYYY-MM-DD (deploy/invites.example.txt).
   */
  file: string;
}

/**
 * KeyEvent reports one completed command (agent, post-command-hook). The
 * same struct is the agent's "key" message without seq and ts.
 */
export interface KeyEvent {
  t: "key";
  seq?: number;
  ts?: number;
  /** Keys is (key-description (this-command-keys-vector)), e.g. "C-x C-f". */
  keys: string;
  /**
   * Cmd is the command symbol name; "<lambda>" for anonymous commands;
   * UndefinedCommand for unbound keys.
   */
  cmd: string;
  /** Buf is the current buffer name after the command. */
  buf: string;
  /** Mode is that buffer's major mode symbol. */
  mode: string;
  /** Frame is the kind of frame the command ran in. */
  frame: FrameKind;
  /** PrefixArg is the printed prefix argument the command received, if any. */
  prefixArg?: string;
  /**
   * Mx is true when the command was run by name through M-x (or another
   * extended command reader); Keys is then the reader's keys, e.g. "M-x".
   */
  mx?: boolean;
}

/**
 * KeysRequest sends keys to the frame. Exactly one of Keys and Text is set.
 * Not idempotent.
 */
export interface KeysRequest {
  /**
   * Keys is a key sequence in Emacs notation ("C-x C-f", "M-x", "<f3>"),
   * validated with ParseKeys. sessiond sends it with tmux send-keys
   * (terminal) or xdotool (gui).
   */
  keys?: string;
  /** Text is typed literally (tmux send-keys -l, xdotool type). */
  text?: string;
  /** Frame selects the frame; default is the current mode. */
  frame?: FrameKind;
}

/** LapInfo describes the running lap (ScenarioRequest.Lap). */
export interface LapInfo {
  lessonId: string;
  /** StartedAt is when the lap's first step became active (ms). */
  startedAt: number;
}

/** LapStats summarises a lesson's finished laps. */
export interface LapStats {
  count: number;
  bestMs: number;
  lastMs: number;
  /** LastAt is when the last lap finished (ms). */
  lastAt: number;
}

/** LessonBundle is GET /api/v1/curriculum/lessons/{lessonId}. */
export interface LessonBundle {
  id: string;
  title: string;
  /** Locale is the locale of Markdown (the best match for the request). */
  locale: string;
  /** Markdown is lesson.md (or project.md) without front matter. */
  markdown: string;
  /** Front is the parsed front matter. */
  front: LessonFront;
  /** Scenario is the parsed scenario with ids assigned (AssignIDs). */
  scenario: Scenario;
  /**
   * Assets are paths relative to the lesson's assets/ directory, served at
   * /api/v1/curriculum/assets/{lessonId}/{path}.
   */
  assets: string[];
}

/** LessonFront is the YAML front matter of lesson.md. */
export interface LessonFront {
  title: string;
  summary?: string;
  minutes?: number;
}

/**
 * LessonProgress is the progress of one lesson. Status is done when every
 * step of the lesson's scenario is done, in-progress when any step is above
 * not-started, else not-started.
 */
export interface LessonProgress {
  status: ProgressStatus;
  counts: ProgressCounts;
  steps: Record<string, StepProgress>;
  /** Laps summarises finished "again, without hints" laps (projects). */
  laps?: LapStats;
}

/** LessonRef is a lesson entry in the index. */
export interface LessonRef {
  /**
   * ID is "<part dir>/<lesson dir>", e.g.
   * "02-buffers-and-files/03-opening-files", or "projects/<dir>".
   */
  id: string;
  /** N is the display number, "2.3" or "P6". */
  n: string;
  title: string;
  minutes: number;
  mode?: LessonMode;
  tags?: string[];
  /** VSCode is the VS Code habit the lesson replaces. */
  vscode?: string;
  status: Availability;
  /** Steps is the number of steps (0 for planned lessons). */
  steps?: number;
}

/** LimitsConfig are per-session resource limits. */
export interface LimitsConfig {
  /** CPUs, default 2. */
  cpus: number;
  /** Memory, default "3g" (Docker size syntax: b, k, m, g). */
  memory: string;
  /** Pids, default 1024. */
  pids: number;
  /**
   * Disk is a volume size hint, default "4g"; enforced only on storage
   * drivers with quotas.
   */
  disk: string;
}

/** LocalConfig configures local mode. */
export interface LocalConfig {
  /**
   * SessionURL is the fixed session's sessiond, default
   * "http://session:7000".
   */
  sessionUrl: string;
  /** Workspace is documented for the Makefile; Compose mounts it. */
  workspace: string;
  /**
   * SessionID is the fixed session's id (PG_SESSION_ID of the session
   * container), default "local". Extension over deployment.md §3.
   */
  sessionId: string;
  /**
   * SessionToken is the fixed session's bearer token for /internal
   * (PG_SESSION_TOKEN of the session container), default "local".
   * Extension over deployment.md §3.
   */
  sessionToken: string;
}

/** LoggingConfig configures slog. */
export interface LoggingConfig {
  /** Level is debug, info (default), warn or error. */
  level: string;
  /** Format is json (default) or text. */
  format: string;
}

/**
 * Me is GET /api/v1/me. Unauthenticated requests get 401 with
 * ErrUnauthenticated; the browser then shows /login using AuthMode from
 * GET /api/v1/auth/config.
 */
export interface Me {
  user: User;
  mode: DeployMode;
  authMode: AuthMode;
  features: MeFeatures;
  /** Version is the gateway build version. */
  version?: string;
}

/** MeFeatures tells the browser which optional features are available. */
export interface MeFeatures {
  gui: boolean;
  remoteBox: boolean;
  stuckReports: boolean;
  authorMode: boolean;
}

/** MetricsConfig configures the optional Prometheus endpoint. */
export interface MetricsConfig {
  /** Enabled, default false. */
  enabled: boolean;
  /** Listen, default ":9090". */
  listen: string;
}

/** Minibuffer describes an open minibuffer or isearch. */
export interface Minibuffer {
  /** Depth is (minibuffer-depth); 0 for isearch. */
  depth: number;
  /** Prompt is (minibuffer-prompt), e.g. "Find file: ", or "I-search: ". */
  prompt: string;
  /** Contents is (minibuffer-contents-no-properties) or the isearch string. */
  contents: string;
  /** Kind is prompt or isearch. */
  kind: MinibufferKind;
}

/** MinibufferEvent reports a minibuffer (or isearch) opening or closing. */
export interface MinibufferEvent {
  t: "minibuffer";
  seq?: number;
  ts?: number;
  open: boolean;
  prompt: string;
  depth: number;
  kind: MinibufferKind;
}

/** ModeEvent reports a frame switch. */
export interface ModeEvent {
  t: "mode";
  seq?: number;
  ts?: number;
  mode: FrameKind;
}

/** ModeRequest switches the frame shown to the browser. */
export interface ModeRequest {
  mode: FrameKind;
}

/** ModeResult echoes the mode now active. */
export interface ModeResult {
  mode: FrameKind;
}

/** ModulesEvent reports a module set change. */
export interface ModulesEvent {
  t: "modules";
  seq?: number;
  ts?: number;
  enabled: string[];
  /** Restarting is true while the daemon restarts to load the new set. */
  restarting: boolean;
}

/** ModulesRequest replaces the enabled module set. */
export interface ModulesRequest {
  enabled: string[];
}

/** ModulesResult tells whether the daemon restarts. */
export interface ModulesResult {
  restarting: boolean;
}

/** NudgeEvent is a server-side nudge from a scenario stuck rule. */
export interface NudgeEvent {
  t: "nudge";
  seq?: number;
  ts?: number;
  /**
   * ID is stable per rule so the browser can dismiss it
   * (StuckRule.ID or "<stepId>/stuck/<n>").
   */
  id: string;
  kind: NudgeKind;
  title: string;
  body: string;
}

/** OIDCConfig configures OpenID Connect login. */
export interface OIDCConfig {
  issuer: string;
  clientId: string;
  clientSecretFile: string;
  /** AllowedEmailDomains restricts logins; empty allows any. */
  allowedEmailDomains: string[];
}

/**
 * OpenRequest visits a workspace file in the learner's selected window
 * (the project file tree, frontend.md §9 and §10). Not in api.md §3.4: it
 * replaces the author-only eval the tree would otherwise need.
 */
export interface OpenRequest {
  /** Path is workspace-relative ("polyglot/docs/report.typ"). */
  path: string;
}

/** OpenResult names the buffer now shown. */
export interface OpenResult {
  buffer: string;
}

/** Part is one part of the course (CURRICULUM.md Part A). */
export interface Part {
  /** N is the part number, 0 to 14. */
  n: number;
  /** ID is the part directory name, e.g. "02-buffers-and-files". */
  id: string;
  title: string;
  minutes: number;
  /** Outcome is one sentence: what the learner can do after the part. */
  outcome: string;
  /**
   * Modules are the configuration modules this part turns on (the delta
   * over earlier parts; Part 0 lists base and agent).
   */
  modules: string[];
  /** Status is ready when every lesson exists, planned otherwise. */
  status: Availability;
  /**
   * SuggestedAfter is the part number recommended first (course map shows
   * "suggested after part N"; order is not enforced). Absent for part 0.
   */
  suggestedAfter?: number;
  /** Lessons in order. For Part 14 these reference the projects. */
  lessons: LessonRef[];
}

/**
 * PrefixEvent reports a pending prefix key sequence (backend.md §3.6). It is
 * advisory: the next KeyEvent supersedes it. Keys == "" means "no prefix
 * pending any more" (sent by the tap when a sequence ends without an agent
 * key event, for example after C-g).
 */
export interface PrefixEvent {
  t: "prefix";
  seq?: number;
  ts?: number;
  keys: string;
  source: PrefixSource;
}

/** PreviewEntry is one item of a directory listing from GET /preview/{dir}/. */
export interface PreviewEntry {
  name: string;
  dir: boolean;
  size: number;
  /** Mtime is the modification time in ms since the epoch. */
  mtime: number;
}

/** PreviewListing is the JSON body of GET /preview/{dir}/. */
export interface PreviewListing {
  /** Path is the listed directory relative to the workspace, "" for the root. */
  path: string;
  entries: PreviewEntry[];
}

/** PreviewSpec configures the preview pane. */
export interface PreviewSpec {
  /** Tabs are workspace-relative files opened as preview tabs. */
  tabs?: string[];
  /**
   * Follow maps a source file to the artefact shown while that source is
   * the current buffer, e.g. {"docs/report.typ": "docs/report.pdf"}.
   */
  follow?: Record<string, string>;
}

/** Problem is the body of every error response (RFC 9457 subset, api.md §1). */
export interface Problem {
  /** Status repeats the HTTP status code. */
  status: number;
  /** Code is the stable error code. */
  code: ErrorCode;
  /** Message is a human-readable sentence safe to show to learners. */
  message: string;
  /** Details is optional structured context (field errors, retry hints). */
  details?: unknown;
}

/** Progress is GET /api/v1/progress. */
export interface Progress {
  lessons: Record<string, LessonProgress>;
  updatedAt: number;
}

/** ProgressCounts counts a lesson's steps by status. */
export interface ProgressCounts {
  done: number;
  demonstrated: number;
  skipped: number;
  /**
   * Total is the number of steps in the bundle's scenario (0 when the
   * lesson is not in the loaded bundle).
   */
  total: number;
}

/**
 * ProgressReport is POST /internal/sessions/{id}/progress from sessiond.
 * HintsUsed and Resets, when present, are the step's absolute totals since
 * the step's progress was last reset (not increments).
 */
export interface ProgressReport {
  lessonId: string;
  stepId: string;
  status: ProgressStatus;
  hintsUsed?: number;
  resets?: number;
  /**
   * At is when the change happened (ms); the gateway uses it as
   * completedAt for done.
   */
  at?: number;
  /**
   * LapMs, on the done report of a lap's last step, records a finished
   * lap of this many milliseconds.
   */
  lapMs?: number;
}

/**
 * ProgressResetRequest is POST /api/v1/progress/reset. An empty LessonID
 * (or no body at all) clears every lesson of the user ("Start over").
 */
export interface ProgressResetRequest {
  lessonId?: string;
}

/** ProjectRef is a project entry (CURRICULUM.md Part 14). */
export interface ProjectRef {
  /** ID is "projects/<dir>", e.g. "projects/p6-polyglot". */
  id: string;
  /** N is "P1" to "P8". */
  n: string;
  title: string;
  minutes: number;
  languages: string[];
  vscode?: string;
  tags?: string[];
  status: Availability;
  tasks: ProjectTask[];
}

/**
 * ProjectSpec configures a project (CURRICULUM.md Part 14, frontend.md
 * §10). Its tasks are the scenario's steps.
 */
export interface ProjectSpec {
  /**
   * Roots are the workspace-relative directories the file tree shows as
   * separate roots ("polyglot/service", "polyglot/report"); default
   * setup.root.
   */
  roots?: string[];
  /**
   * LapMinutes is the target time of the "again, without hints" lap
   * (ScenarioRequest.Lap); 0 shows the timer without a target.
   */
  lapMinutes?: number;
}

/**
 * ProjectTask is one task of a project; it is a step of the project's
 * scenario with the same id.
 */
export interface ProjectTask {
  id: string;
  n: number;
  title: string;
}

/**
 * PtyControl is a text frame on /pty, e.g. {"t":"resize","cols":120,"rows":36},
 * {"t":"ping"}, {"t":"attached"}, {"t":"replaced"}.
 */
export interface PtyControl {
  t: PtyControlType;
  cols?: number;
  rows?: number;
}

/** RemoteBoxConfig configures the per-learner SSH box. */
export interface RemoteBoxConfig {
  /** Enabled provisions an SSH box per learner, default true. */
  enabled: boolean;
  image: string;
}

/** RemoteSpec requests the SSH box. */
export interface RemoteSpec {
  box: boolean;
}

/**
 * RescueResult lists what playground-rescue did, as short sentences
 * ("cancelled the prompt", "closed the extra windows").
 */
export interface RescueResult {
  did: string[];
}

/**
 * RestoreRequest restores a checkpoint by label or ref (exactly one). An
 * empty request restores the active step's checkpoint. Not idempotent.
 */
export interface RestoreRequest {
  label?: string;
  ref?: string;
}

/**
 * RestoreResult reports how many files the restore changed: restored or
 * removed on disk, or with unsaved changes in their buffer that the
 * restore discarded (each file once).
 */
export interface RestoreResult {
  restoredFiles: number;
}

/**
 * Scenario is the parsed scenario.yaml of a lesson or project
 * (CURRICULUM.md Part B.3, api.md §6). The gateway serves it inside
 * LessonBundle; sessiond fetches it from /internal/curriculum/scenarios.
 *
 * YAML is decoded by converting it to JSON (goccy/go-yaml YAMLToJSON) and
 * unmarshalling into these types, so the JSON tags below are also the YAML
 * keys.
 */
export interface Scenario {
  /**
   * ID is the lesson id: the lesson directory relative to the curriculum
   * root, e.g. "02-buffers-and-files/03-opening-files" or
   * "projects/p6-polyglot".
   */
  id: string;
  /** Title is the lesson title. */
  title: LocalText;
  /** Minutes is the rough duration. */
  minutes: number;
  /** Mode is the frame the lesson needs: terminal (default), gui or any. */
  mode?: LessonMode;
  /** Tags: remote, gui, project. */
  tags?: string[];
  /**
   * Modules is the full module set enabled while the lesson runs, in load
   * order.
   */
  modules: string[];
  /** VSCode names the VS Code habit the lesson replaces. */
  vscode?: string;
  /** Preview configures the preview pane (optional). */
  preview?: PreviewSpec;
  /** Remote requests the SSH box (optional). */
  remote?: RemoteSpec;
  /**
   * Project configures a project's screen and its "again, without
   * hints" lap (projects only, optional).
   */
  project?: ProjectSpec;
  /** Setup prepares the workspace and Emacs when the scenario loads. */
  setup: Setup;
  /** Steps are the lesson's goals in order. */
  steps: Step[];
}

/** ScenarioRequest loads a lesson's scenario (architecture.md §3.3). */
export interface ScenarioRequest {
  lessonId: string;
  /**
   * StepID starts at a given step; default: the first step not yet
   * complete according to sessiond's state, else the first step.
   */
  stepId?: string;
  /** Reset forces fixture extraction over learner files (setup.reset). */
  reset?: boolean;
  /**
   * Lap starts the "again, without hints" lap of a project: the lesson
   * loads with reset from its first step (StepID must be empty or the
   * first step) and a timer starts; until the last step completes, hint,
   * demo and skip answer 409 and stuck rules are silent. Any other load
   * ends the lap.
   */
  lap?: boolean;
}

/** ScenarioResult reports the loaded step. */
export interface ScenarioResult {
  step: StepRef;
  /** Index and Count locate the step in the scenario. */
  index: number;
  count: number;
  /** Modules is the module set now enabled. */
  modules: string[];
  /**
   * Restarting is true when loading changed the module set and the daemon
   * is restarting (the step becomes active after the restart).
   */
  restarting: boolean;
  /**
   * Lap is set when the request started a lap; StartedAt is 0 until the
   * first step is active (after a restart).
   */
  lap?: LapInfo;
}

/**
 * SessionInfo is the body of POST /api/v1/sessions (201) and
 * GET /api/v1/sessions/{id}. Emacs, Mode and Step come from sessiond's
 * /status when the session is running.
 */
export interface SessionInfo {
  id: string;
  state: SessionState;
  createdAt: number;
  lastActiveAt?: number;
  image?: string;
  /** GUI is true when the GUI frame is available for this session. */
  gui: boolean;
  /** Failure is the reason when State is failed. */
  failure?: string;
  emacs?: EmacsInfo;
  mode?: FrameKind;
  step?: StepRef;
  /**
   * UpdateAvailable is true when the session runs an older image than the
   * gateway's configured one ("restart to update" chip).
   */
  updateAvailable?: boolean;
}

/** SessionsConfig configures session provisioning. */
export interface SessionsConfig {
  /**
   * Backend is static (default in local mode) or docker (default in server
   * mode).
   */
  backend: SessionBackend;
  /**
   * DockerHost is the Engine API endpoint, normally the socket proxy
   * ("tcp://socket-proxy:2375"); empty uses DOCKER_HOST.
   */
  dockerHost: string;
  /** Image is the session image. */
  image: string;
  /**
   * Network is the Docker network shared by session containers with
   * isolation shared.
   */
  network: string;
  /**
   * Isolation is network (default): every session gets its own internal
   * network pg-net-<id> that the gateway joins, so sessions cannot reach
   * each other; or shared: all sessions join Network.
   */
  isolation: SessionIsolation;
  /**
   * SubnetPool is the IPv4 range session networks take their /28 subnets
   * from, default "10.231.0.0/16" (4096 sessions). Empty lets the Docker
   * daemon choose from its default-address-pools, which hold about 30
   * networks unless configured.
   */
  subnetPool: string;
  /**
   * GatewayContainer is the gateway's own container (name or id), which
   * joins every session network; default the gateway's hostname, which
   * Docker sets to the container id.
   */
  gatewayContainer: string;
  /** Runtime is runc (default) or runsc (gVisor). */
  runtime: string;
  limits: LimitsConfig;
  /**
   * IdleStopMinutes stops a session with no WebSocket for this long,
   * default 30.
   */
  idleStopMinutes: number;
  /** MaxSessions refuses new sessions beyond this, default 50. */
  maxSessions: number;
  /**
   * VolumeRetentionDays removes workspace volumes unused for this long,
   * default 30.
   */
  volumeRetentionDays: number;
  /** Egress is none, registries (default) or all. */
  egress: EgressPolicy;
  remoteBox: RemoteBoxConfig;
  gui: GUIConfig;
  terminal: TerminalConfig;
}

/** Setup prepares the workspace and Emacs for a scenario. */
export interface Setup {
  /**
   * Workspace is the fixture directory relative to the lesson directory,
   * e.g. "fixtures/hello-rust". Empty: no fixtures.
   */
  workspace?: string;
  /**
   * Root is the directory under /work the fixtures extract to, e.g.
   * "hello" for /work/hello.
   */
  root?: string;
  /**
   * Reset restores Root to the fixtures: learner edits are overwritten and
   * files the fixtures do not contain are removed (build directories such
   * as target/ and .venv/ are kept). Emacs reverts the affected buffers
   * and clears unmodified leftovers (AgentSetupArgs.Reset).
   */
  reset?: boolean;
  /** Open lists workspace-relative files to visit, e.g. "hello/README.md". */
  open?: string[];
  /**
   * Layout is "single", a layout pattern such as
   * "(vsplit hello/src/main.rs *compilation*)", or a window-state file
   * relative to the lesson directory (ending in .eld).
   */
  layout?: string;
  /** Eval is an Emacs Lisp form run after Open and Layout. */
  eval?: string;
  /**
   * Compile is a command run once so *compilation* exists; null or empty
   * for none. It runs in the project root (project.el) of the first Open
   * file, or that file's directory when it is in no project.
   */
  compile?: string;
  /**
   * Repos are directories relative to Root ("." for Root itself) made
   * git repositories of their own, with the fixtures as one initial
   * commit (fixed identity and date, branch main), when they have no
   * .git yet or the load resets. Checkpoints capture such nested
   * repositories whole (.git included, so the staging area and commits
   * made in a step are restored too).
   */
  repos?: string[];
  /**
   * Run is a shell script sessiond runs as the learner (sh -c) in Root
   * after the fixtures and Repos and before Emacs opens anything, on
   * every load; at most SetupRunTimeout. It must be idempotent (a git
   * history for a Magit lesson, files on the box over ssh). A failure is
   * logged and reported as an error event.
   */
  run?: string;
}

/**
 * ShellCond runs `sh -c Run` as the learner; exit status 0 is true.
 * A run longer than about a second does not hold up the step's other
 * conditions: it is unknown ("running") until it finishes, and its result
 * is kept until the next file event or step change.
 */
export interface ShellCond {
  run: string;
  /**
   * Cwd is workspace-relative; default the scenario's setup root. With
   * Host it is a directory on the box (default the box user's home).
   */
  cwd?: string;
  /**
   * Timeout in seconds, default 5, at most MaxShellTimeout; a timeout
   * yields unknown.
   */
  timeout?: number;
  /**
   * Host is "" (the session) or BoxHost: the script runs on the remote
   * box over ssh.
   */
  host?: string;
}

/**
 * SkipRequest asks sessiond to do the active step for the learner ("Skip
 * this step", api.md §3.4). The RPC fails with ErrConflict unless StepID is
 * the active step. Not idempotent.
 */
export interface SkipRequest {
  stepId: string;
}

/** SkipResult names the step now active. */
export interface SkipResult {
  /**
   * Next is the id of the step loaded after the skipped one, or null when
   * the skipped step was the last (the lesson is complete).
   */
  next: string | null;
  /**
   * DemoCompleted is true when the step's conditions held after sessiond
   * played its demo (false means a curriculum defect; the step is skipped
   * anyway).
   */
  demoCompleted: boolean;
}

/**
 * State is the snapshot of the selected window's buffer and the frame layout
 * that the agent emits after commands and UI changes (api.md §5, emacs.md
 * §10.2). sessiond forwards it unchanged apart from stamping seq and ts.
 * The browser's exits table and the step engine's state and layout
 * conditions read it; field names are the paths used by those predicates
 * (for example "minibuffer.kind" or "windows.length").
 */
export interface State {
  t: "state";
  seq?: number;
  ts?: number;
  /** Buf is the selected window's buffer name, e.g. "main.rs" or "*Help*". */
  buf: string;
  /** File is the absolute path the buffer visits, or null. */
  file: string | null;
  /** Mode is the major mode symbol, e.g. "rust-ts-mode". */
  mode: string;
  /** ModeName is the mode line lighter of the major mode, e.g. "Rust". */
  modeName: string;
  /**
   * Minors lists the enabled minor mode symbols the agent considers
   * interesting (eglot--managed-mode, flymake-mode, overwrite-mode, ...).
   */
  minors: string[];
  /** Modified is buffer-modified-p. */
  modified: boolean;
  /** Readonly is buffer-read-only. */
  readonly: boolean;
  /** Narrowed is buffer-narrowed-p. */
  narrowed: boolean;
  /** Overwrite is true when overwrite-mode is on. */
  overwrite: boolean;
  /** Line is the 1-based line of point. */
  line: number;
  /** Col is the 0-based column of point (current-column). */
  col: number;
  /** Point is the 1-based buffer position of point. */
  point: number;
  /** MarkActive is region-active-p. */
  markActive: boolean;
  /**
   * Windows lists the live windows of the selected frame in window-list
   * order (selected window first is NOT guaranteed; use Selected).
   */
  windows: Window[];
  /** Layout is the window tree of the selected frame. */
  layout: Layout;
  /** Frame is the kind of the selected frame. */
  frame: FrameKind;
  /**
   * Frames is (length (frame-list)), including the invisible daemon frame
   * as Emacs reports it.
   */
  frames: number;
  /** Tabs describes tab-bar tabs of the selected frame. */
  tabs: Tabs;
  /** Minibuffer is the active minibuffer, or null when none is open. */
  minibuffer: Minibuffer | null;
  /** Isearch is true while an incremental search is active. */
  isearch: boolean;
  /** Recursive is (recursion-depth). */
  recursive: number;
  /** Macro is true while a keyboard macro is being defined. */
  macro: boolean;
  /** PrefixArg is the printed current-prefix-arg ("(4)", "-", "3"), or null. */
  prefixArg: string | null;
  /**
   * ReadOnlyReason explains why the buffer is read-only when the agent
   * knows ("special-mode", "file is write-protected", "view-mode"), or null.
   */
  readOnlyReason: string | null;
  /** DiagAtPoint is the Flymake diagnostic at point, or null. */
  diagAtPoint: Diagnostic | null;
  /**
   * Waiting names a loop that reads keys of its own (a menu-bar menu,
   * avy, which-key's pages), or null. Such a loop is neither a prompt nor
   * a recursive edit, and every key goes to it.
   */
  waiting: Waiting | null;
}

/** StatusResult is the result of rpc status and the body of GET /status. */
export interface StatusResult {
  sessionId: string;
  emacs: EmacsStatus;
  frames: Frames;
  mode: FrameKind;
  step: StepRef | null;
  modules: string[];
  /** Versions are the toolchain versions from images/session/versions.env. */
  versions?: Record<string, string>;
  /** ActiveWebSockets counts open /pty, /events and /vnc connections. */
  activeWebSockets: number;
  /** Lap is the running lap, if any. */
  lap?: LapInfo;
  /**
   * RemoteBox is true when the box alias is set up (key pair and
   * ~/.ssh/config written; deployment.md §6).
   */
  remoteBox?: boolean;
}

/** Step is one goal of a lesson. */
export interface Step {
  /** ID is unique within the scenario, [a-z0-9-]+. */
  id: string;
  /** Goal is the one-line goal shown in the step list. */
  goal: LocalText;
  /** Detail is a longer explanation (Markdown, keys keyified). */
  detail?: LocalText;
  /**
   * Demo is a demo string that completes the step when replayed
   * (ParseDemo); required for every step (ADR-017).
   */
  demo?: string;
  /** Conditions are ordered: the hint shown is the first unmet one's. */
  conditions: Condition[];
  /** Stuck rules produce server-side nudges. */
  stuck?: StuckRule[];
  /**
   * Checkpoint takes a checkpoint when the step starts. Default true; set
   * false explicitly to skip (a pointer so absence means default).
   */
  checkpoint?: boolean;
  /**
   * Mode is the frame this step needs when the lesson's mode does not
   * say it (a project task with images or PDF pages): gui switches to
   * the GUI frame when the step becomes active, as a gui lesson does on
   * load.
   */
  mode?: LessonMode;
}

/**
 * StepEvent reports step transitions. After "complete" and "skipped" the
 * engine advances and emits "loaded" for the next step; for the last step it
 * sets LessonComplete instead.
 */
export interface StepEvent {
  t: "step";
  seq?: number;
  ts?: number;
  lessonId: string;
  stepId: string;
  status: StepStatus;
  /** Index is the 0-based position of the step in the scenario. */
  index: number;
  /** Count is the number of steps in the scenario. */
  count: number;
  /**
   * LessonComplete is true on the "complete" or "skipped" event of the
   * last step.
   */
  lessonComplete?: boolean;
  /** Lap is true while the step belongs to a lap (ScenarioRequest.Lap). */
  lap?: boolean;
  /** LapMs is the lap's time, on the event that completes it. */
  lapMs?: number;
}

/** StepProgress is the progress of one step. */
export interface StepProgress {
  status: ProgressStatus;
  hintsUsed: number;
  resets: number;
  completedAt?: number;
}

/**
 * StepRef identifies a step of a lesson. Lesson ids contain one slash
 * ("02-buffers-and-files/03-opening-files"); step ids are unique within the
 * lesson ("open").
 */
export interface StepRef {
  lessonId: string;
  stepId: string;
}

/**
 * StuckRPCRequest asks sessiond for its recent events (it also files the
 * report with the gateway when called by the browser directly).
 */
export interface StuckRPCRequest {
  note: string;
}

/**
 * StuckRPCResult returns the last 200 events, oldest first, as raw JSON
 * frames exactly as sent on /events.
 */
export interface StuckRPCResult {
  events: unknown[];
}

/** StuckRequest is POST /api/v1/stuck (the "I'm stuck" button). */
export interface StuckRequest {
  sessionId: string;
  lessonId?: string;
  stepId?: string;
  note: string;
}

/** StuckRule emits a nudge when its When holds for the active step. */
export interface StuckRule {
  /** ID overrides the derived id StuckRuleID(stepID, index). */
  id?: string;
  when: StuckWhen;
  /** Say is the nudge body. */
  say: LocalText;
  /** Title is the nudge title; default: the first sentence of Say. */
  title?: LocalText;
  /** Kind is the nudge tone, default calm. */
  kind?: NudgeKind;
}

/**
 * StuckWhen is a conjunction of time and key-stream thresholds; every set
 * field must hold. Evaluated by sessiond on its 2 s ticker.
 */
export interface StuckWhen {
  /** MinibufferSeconds: a minibuffer has been open this long. */
  minibuffer_seconds?: number;
  /** IdleSeconds: no key event for this long. */
  idle_seconds?: number;
  /** StepSeconds: the step has been active this long. */
  step_seconds?: number;
  /**
   * QuitsInWindow: at least Count quits (keyboard-quit,
   * abort-minibuffers, abort-recursive-edit) within Seconds.
   */
  quits_in_window?: CountWindow;
  /**
   * UnboundRepeats: the same unbound key sequence this many times in a
   * row.
   */
  unbound_repeats?: number;
}

/**
 * Tables are the advice tables (CURRICULUM.md Part B.4), shipped in the
 * curriculum index for the browser's advice engine.
 */
export interface Tables {
  /** Exits: layer 1, evaluated in order against the State object. */
  exits: ExitRow[];
  /** Habits: layer 2, VS Code muscle memory translations. */
  habits: HabitRow[];
  /** Gloss maps a command name to a short gloss for the ticker. */
  gloss: Record<string, string>;
  /**
   * Cheats maps a major mode to cheat-sheet rows; key CheatsCommon holds
   * rows shown in every mode.
   */
  cheats: Record<string, CheatRow[]>;
  /** Glossary maps a term to its tooltip text for :jargon[term]. */
  glossary: Record<string, string>;
}

/** Tabs describes the tab bar of the selected frame. */
export interface Tabs {
  /** Count is the number of tabs (1 when tab-bar-mode is off). */
  count: number;
  /** Current is the current tab's name. */
  current: string;
}

/** TerminalConfig configures the terminal frame. */
export interface TerminalConfig {
  /**
   * InitialSize is "COLSxROWS" until the browser resizes, default
   * "120x36".
   */
  initialSize: string;
}

/** User is the authenticated learner. */
export interface User {
  id: string;
  displayName: string;
  kind: UserKind;
}

/** Waiting describes a loop that reads keys of its own. */
export interface Waiting {
  /** Kind is the loop. */
  kind: WaitingKind;
  /** What says what is waiting, for people ("a menu"). */
  what: string;
  /**
   * Leave is the keys that leave it ("C-g"; "a" for which-key, where
   * C-g only goes back to the prefix). Rescue sends them.
   */
  leave: string;
}

/** Window is one live window of the selected frame. */
export interface Window {
  /**
   * ID is a small integer stable for the lifetime of the window, assigned
   * by the agent; Layout leaves refer to it.
   */
  id: number;
  /** Buf is the buffer name shown in the window. */
  buf: string;
  /** Mode is that buffer's major mode symbol. */
  mode: string;
  /** Selected is true for the selected window. */
  selected: boolean;
  /** Dedicated is true when window-dedicated-p is non-nil. */
  dedicated: boolean;
  /**
   * Side is the window-side parameter ("left", "right", "top", "bottom")
   * for side windows, or null.
   */
  side: string | null;
}

/**
 * WindowSpec is the buffer and window spec saved with each checkpoint and
 * periodically for restart restore (backend.md §3.9, emacs.md §7). It is
 * the result of the snapshot op and the argument of open and reset-step.
 */
export interface WindowSpec {
  /** Files are the file-visiting buffers, most recently used first. */
  files: FileSpec[];
  /**
   * Layout is a simple layout description used when WindowState is empty:
   * "single" or a layout pattern over workspace-relative paths, e.g.
   * "(vsplit hello/src/main.rs *compilation*)".
   */
  layout?: string;
  /**
   * WindowState is the printed (window-state-get nil t) of the selected
   * frame; opaque to sessiond; preferred over Layout when present.
   */
  windowState?: string;
  /**
   * Selected is the workspace-relative path or buffer name of the selected
   * window's buffer.
   */
  selected?: string;
  /** Tab is the current tab-bar tab name. */
  tab?: string;
  /**
   * Tabs are the names of the frame's tab-bar tabs in order, "" for a
   * tab without an explicit name (its name follows its buffer). A
   * reset-step closes the named tabs the list does not have and brings
   * back the named ones it misses, so a step's demo leaves no tab
   * behind. Absent when the snapshot was taken without tab-bar.
   */
  tabs?: string[];
  /** TabIndex is the 1-based position of the current tab in Tabs. */
  tabIndex?: number;
  /**
   * SpecialBuffers is the printed list of the non-file buffers the agent
   * can make again (help buffers: name and the help command that made
   * them); opaque to sessiond. A reset-step makes the missing ones again
   * and kills the help buffers it does not list, so a demo that killed
   * or opened help buffers leaves the step as it started (lesson 2.5).
   */
  specialBuffers?: string;
  /** TakenAt is when the snapshot was taken (ms). */
  takenAt?: number;
}

/** Every event on /s/{id}/events, discriminated by `t` (api.md §4). */
export type Event = HelloEvent | KeyEvent | PrefixEvent | State | EchoEvent | MinibufferEvent | EmacsEvent | FileEvent | CheckEvent | StepEvent | NudgeEvent | CheckpointEvent | ModeEvent | ModulesEvent | GapEvent | ErrorEvent;

/** Session RPC success body (api.md §3.4). */
export interface RpcOk<T> {
  ok: true;
  result: T;
}

/** Request and result types per session RPC op: POST /s/{id}/rpc/{op}. */
export interface RpcOps {
  "keys": { request: KeysRequest; result: Empty };
  "eval": { request: EvalRequest; result: EvalResult };
  "rescue": { request: Empty; result: RescueResult };
  "scenario": { request: ScenarioRequest; result: ScenarioResult };
  "check": { request: Empty; result: CheckResult };
  "hint": { request: HintRequest; result: Empty };
  "checkpoint": { request: CheckpointRequest; result: CheckpointResult };
  "checkpoints": { request: Empty; result: CheckpointsResult };
  "restore": { request: RestoreRequest; result: RestoreResult };
  "mode": { request: ModeRequest; result: ModeResult };
  "modules": { request: ModulesRequest; result: ModulesResult };
  "restart-emacs": { request: Empty; result: Empty };
  "stuck": { request: StuckRPCRequest; result: StuckRPCResult };
  "status": { request: Empty; result: StatusResult };
  "describe": { request: DescribeRequest; result: DescribeResult };
  "drop-step": { request: DropStepRequest; result: Empty };
  "open": { request: OpenRequest; result: OpenResult };
  "demo": { request: DemoRequest; result: DemoResult };
  "skip": { request: SkipRequest; result: SkipResult };
}

